import{sideIRSelection,setSideIRFamily,setSideIRCoverLength,setSideIRHandleLength}from'./side-ir-service-state.js';
export function renderSideIRControls(task,language,refresh){
 let host=document.getElementById('side-ir-service-choice');if(!host){host=document.createElement('div');host.id='side-ir-service-choice';}const reference=document.querySelector('.service-reference');if(host.parentElement!==reference)reference.append(host);host.hidden=!task.sideIRService;if(host.hidden)return;host.textContent='';
 const n=Math.max(0,['ja','en','cs','de'].indexOf(language)),s=sideIRSelection(),select=(name,options,value,change)=>{const label=document.createElement('label');label.className='firmware-action';label.textContent=name[n];const input=document.createElement('select');input.style.fontSize='16px';input.style.minHeight='44px';input.style.touchAction='manipulation';input.setAttribute('aria-label',label.textContent);for(const[id,text]of options){const o=document.createElement('option');o.value=id;o.textContent=text[n];o.selected=String(id)===String(value);input.append(o);}input.onchange=()=>{change(input.value);refresh();};label.append(input);host.append(label);};
 select(['実物のセンサー本体','Sensor housing on your printer','Pouzdro senzoru na tiskárně','Sensorgehäuse am Drucker'],[['r1-one',['旧型・片側のねじを外すカバー','Original · one-side cover release','Původní · uvolnění krytu na jedné straně','Ursprünglich · Abdeckung einseitig lösen']],['r1-two',['旧型・ねじ2本のカバー','Original · two-screw cover','Původní · kryt se dvěma šrouby','Ursprünglich · Abdeckung mit zwei Schrauben']],['plus',['One+・スイッチ付きR2本体','One+ · switched R2 body','One+ · tělo R2 s přepínačem','One+ · R2-Gehäuse mit Schalter']]],s.family,setSideIRFamily);
 if(s.family==='plus')select(['外したカバーねじの長さ','Length of removed cover screws','Délka vyjmutých šroubů krytu','Länge der ausgebauten Deckelschrauben'],[[8,['M3x8','M3x8','M3x8','M3x8']],[10,['M3x10','M3x10','M3x10','M3x10']]],s.coverLength,setSideIRCoverLength);
 select(['外したハンドルねじの長さ','Length of removed handle screws','Délka vyjmutých šroubů rukojeti','Länge der ausgebauten Griffschrauben'],[[8,['M3x8rT','M3x8rT','M3x8rT','M3x8rT']],[10,['M3x10rT','M3x10rT','M3x10rT','M3x10rT']]],s.handleLength,setSideIRHandleLength);
}
